module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    wire [7:0] shifted_left = data_in << 1;
    wire [7:0] shifted_right = data_in >> 1;
    wire [7:0] sum = shifted_left + shifted_right;
    wire [7:0] rotated = {sum[6:0], sum[7]};
    wire [7:0] reversed = {rotated[0], rotated[1], rotated[2], rotated[3],
                             rotated[4], rotated[5], rotated[6], rotated[7]};

    assign data_out = reversed;

endmodule

