  input clk,
  input in,
  input reset,
  output out
);

  reg [7:0] shift_reg;
  reg [2:0] counter;
  reg [1:0] cycle_count;

  wire shift_active = reset && ~in;

  always @(posedge clk) begin
    if (reset && ~in) begin
      shift_reg <= {shift_reg[6:0], 1'b0};
      if (counter < 3'd7)
        counter <= counter + 1;
    end
  end

  always @(posedge clk) begin
    if (counter == 3'd7) begin
      cycle_count <= cycle_count + 1;
    end
  end

  assign out = shift_active ? shift_reg[7] : 1'b0;

endmodule

