module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  // Define states
  localparam [1:0] s0 = 2'b00,
                   s1 = 2'b01,
                   s2 = 2'b10,
                   s3 = 2'b11;

  reg [1:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (reset)
      current_state <= s0;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      s0: next_state = in[0] ? s1 : s0;
      s1: next_state = in[1] ? s2 : s1;
      s2: next_state = in[2] ? s3 : s2;
      s3: next_state = s3; // Maintain state once reached
      default: next_state = s0;
    endcase
  end

  // Output logic
  assign done = (current_state == s3);

endmodule

